module TopModule (
  input [254:0] in,
  output reg [7:0] out
);

  integer i;
  reg [7:0] count;

  always @(*) begin
    count = 8'd0;
    // Iterate through each bit of the input vector
    for (i = 0; i < 255; i = i + 1) begin
      if (in[i]) begin
        count = count + 1;
      end
    end
    out = count;
  end

endmodule
